def login_view(request):
    user = authenticate(request, **credentials)
    django_login(request, user)          # calls request.session.cycle_key()
    request.session.set_expiry(1800)     # idle window; 0 -> expire at browser close

def logout_view(request):
    django_logout(request)               # request.session.flush(): data + cookie gone
